import{_ as a,o as t,c as o,a4 as r}from"./chunks/framework.CW-6O5Zu.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/courses/Electron + React 从 0 到 1 实现简历平台实战/13-1000米里程碑 ｜简历主流程完成.md","filePath":"knowledge/courses/Electron + React 从 0 到 1 实现简历平台实战/13-1000米里程碑 ｜简历主流程完成.md","lastUpdated":1776396922000}'),n={name:"knowledge/courses/Electron + React 从 0 到 1 实现简历平台实战/13-1000米里程碑 ｜简历主流程完成.md"};function l(c,e,_,s,i,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="🏆-1000-米里程碑-简历主流程完成" tabindex="-1">🏆 1000 米里程碑 ｜简历主流程完成 <a class="header-anchor" href="#🏆-1000-米里程碑-简历主流程完成" aria-label="Permalink to &quot;🏆 1000 米里程碑 ｜简历主流程完成&quot;">​</a></h2><p>很高兴你看到这章，第二阶段的里程碑很长。通过这六个章节，此刻你已经解决了<strong>几大问题</strong>：</p><ol><li>数据存储的了解和最终实现设计</li><li>通用组件的封装思考与实现</li><li>简单数据类型与复杂数据类型的录入</li><li>网页导出成 PDF 文档的方案对比与功能实现</li></ol><p>磕磕撞撞终于将简历应用平台搭建起来并走完一个主流程，不可否认的是，现在的应用还是不够完美的，在接下来的第三阶段，我将陆陆续续添加部分功能，从而让我们的应用更加丰富。</p><h2 id="一些话" tabindex="-1">一些话 <a class="header-anchor" href="#一些话" aria-label="Permalink to &quot;一些话&quot;">​</a></h2><p>首先跟部分小伙伴道个歉，因为长篇幅的内容看下来相对吃力，小伙伴也许接受不了长篇幅的冲击。</p><p>其实我也很苦恼，因为主流程的实战操作，特别繁琐和啰嗦，或许一上来直接讲最终的代码实现，文章内容会减少部分，但这并不是我所期望的。我尝试将一章内容拆分成多章节去写，但感觉内容衔接上有些割裂。无奈之下，只能一次次对每章内容进行精简。</p><p>每写完一章节，我都会想，作为读者，我期望在这篇文章中能学到什么？我想，不应该只是代码实现，更重要的是把所思考的过程讲明白。我常常认为，<code>懂</code>跟<code>给别人讲懂</code>这是两个事。如果小伙伴们在章节阅读上，存在任何疑问，哪个地方听听懂，可在评论区留言或直接在群里提出，更有甚者直接加我微信：<code>PPPengDK</code> 私下交流。</p><p>到此阶段，已经将主流程走完，下一里程碑目标：丰富应用功能。</p><h2 id="迫不及待生成第一个桌面应用" tabindex="-1">迫不及待生成第一个桌面应用 <a class="header-anchor" href="#迫不及待生成第一个桌面应用" aria-label="Permalink to &quot;迫不及待生成第一个桌面应用&quot;">​</a></h2><p>许多小伙伴们通过<a href="https://juejin.cn/book/6950646725295996940/section/6961586491285831720" target="_blank" rel="noreferrer">环境篇-动手搭建我们的简历平台</a>章节将 Electron + React 搭建起来后，还没开始写几行代码，就迫不及待想打包成桌面应用，毕竟搞出自己第一个桌面应用，是一件很骄傲自豪的事情！！！但是又不想等整个小册都完结，才能上手打包构建，为此，阿宽新增一章节 <a href="https://juejin.cn/book/6950646725295996940/section/6972047382494052392" target="_blank" rel="noreferrer">🏆 支线篇-打包生成第一个桌面应用（骄傲自豪）</a>。</p><p>此章节为支线任务，与主流程（主线任务）无任何关系。可放心使用，如果在打包期间遇到问题，可加我微信或进群讨论～</p>',12)])])}const u=a(n,[["render",l]]);export{h as __pageData,u as default};
